  // src/js/modules/components/settings-menu.js
  function injectSettingsMenu(containerEl) {
    const createSettingsMenu = () => {
      const settingsMenuEl2 = document.createElement("div");
      settingsMenuEl2.className = "settings-container";
      const settingsMenuHeaderEl = document.createElement("h2");
      settingsMenuHeaderEl.className = "setting-container__title";
      settingsMenuHeaderEl.innerText = "Settings";
      settingsMenuEl2.appendChild(settingsMenuHeaderEl);
      return settingsMenuEl2;
    };
    const settingsMenuEl = createSettingsMenu();
    injectUISettingsSection(settingsMenuEl);
    containerEl.appendChild(settingsMenuEl);
  }
  function handleOutsideSettingsMenuClick(e) {
    const settingsMenu = elements.injected.settingsMenu;
    const settingsMenuToggleBtn = elements.injected.settingsToggleButton;
    if (settingsMenu.contains(e.target) || settingsMenuToggleBtn.contains(e.target)) return;
    hideSettings();
  }
  function handleSettingsEsc(e) {
    if (e.key === "Escape") {
      hideSettings();
    }
  }
  function createNewSettingsSection(sectionTitle) {
    const sectionEl = document.createElement("section");
    const sectionTitleSlug = sectionTitle.trim().replace(/\s+/g, "-").toLowerCase();
    sectionEl.className = `settings-section ${sectionTitleSlug}-section`;
    const sectionHeaderEl = document.createElement("header");
    sectionHeaderEl.className = `settings-section__header ${sectionTitleSlug}-header`;
    sectionHeaderEl.innerText = sectionTitle;
    const settingsListEl = document.createElement("ul");
    settingsListEl.className = "settings-list";
    sectionEl.append(sectionHeaderEl);
    sectionEl.append(settingsListEl);
    return sectionEl;
  }
  function createNewSetting(settingDesc, settingTogglerId) {
    const settingListItemEl = document.createElement("li");
    settingListItemEl.className = "settings-list__item";
    const settingTextEl = document.createElement("span");
    settingTextEl.className = "setting-desc";
    settingTextEl.innerText = settingDesc;
    const settingTogglerEl = createNewSettingToggler(settingTogglerId);
    settingListItemEl.append(settingTogglerEl);
    settingListItemEl.append(settingTextEl);
    return settingListItemEl;
  }
  function createNewSettingToggler(id) {
    const togglerEl = document.createElement("span");
    togglerEl.className = "toggler setting-status";
    const togglerInputEl = document.createElement("input");
    const togglerLabelEl = document.createElement("label");
    togglerInputEl.id = id;
    togglerInputEl.name = id;
    togglerInputEl.type = "checkbox";
    togglerInputEl.value = 1;
    togglerLabelEl.htmlFor = id;
    togglerLabelEl.innerHTML = `
      <svg class="toggler-on" version="1.1" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 130.2 130.2">
        <polyline class="path check" points="100.2,40.2 51.5,88.8 29.8,67.5"></polyline>
      </svg>
      <svg class="toggler-off" version="1.1" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 130.2 130.2">
        <line class="path line" x1="34.4" y1="34.4" x2="95.8" y2="95.8"></line>
        <line class="path line" x1="95.8" y1="34.4" x2="34.4" y2="95.8"></line>
      </svg>
    `;
    togglerEl.append(togglerInputEl);
    togglerEl.append(togglerLabelEl);
    return togglerEl;
  }
  function injectUISettingsSection(containerEl) {
    const createUISettingsSection = () => {
      const uiSettingsSectionEl = createNewSettingsSection("UI Options");
      const uiSettingsListEl = uiSettingsSectionEl.querySelector(".settings-list");
      const createSettingSidebarHiddenHeadersEl = () => {
        const settingDesc = "Hide expanded sidebar's section headers";
        const settingTogglerId = "setting--sidebar-hidden-headers";
        return createNewSetting(settingDesc, settingTogglerId);
      };
      const createSettingSidebarShrinkEl = () => {
        const settingDesc = "Shrink sidebar instead of hiding it when collapsed";
        const settingTogglerId = "setting--sidebar-shrink";
        return createNewSetting(settingDesc, settingTogglerId);
      };
      uiSettingsListEl.append(createSettingSidebarHiddenHeadersEl());
      uiSettingsListEl.append(createSettingSidebarShrinkEl());
      return uiSettingsSectionEl;
    };
    containerEl.append(createUISettingsSection());
  }

  // src/js/modules/utils/sync/active-sidebar-item.js
  function syncActiveSidebarItem() {
    const currentUrl = window.location.pathname;
    document.querySelectorAll(".sidebar-list__item a").forEach((link) => {
      const linkClasses = link.classList;
      const linkUrl = new URL(link.href).pathname;
      if (currentUrl.startsWith("/course_catalog/") && linkClasses.contains("courses") || linkUrl === currentUrl) {
        link.classList.add("current-page");
      } else {
        link.classList.remove("current-page");
      }
    });
  }

  // src/js/modules/utils/sync/available-hotkeys.js
  function syncAvailableHotkeys() {
    hotkeys.cmdOnly = {};
    hotkeys.cmdShift = {};
    hotkeys.cmdCtrl = {};
    syncCmdOnlyHotkeys();
    syncCmdShiftHotkeys();
    syncCmdCtrlHotkeys();
  }
  function syncCmdOnlyHotkeys() {
    if (elements.native.sidebar) setAvailableHotkey("cmdOnly", "KeyB", "B", "Toggle Sidebar Visibility", toggleSidebar);
  }
  function syncCmdShiftHotkeys() {
    if (elements.injected.header) setAvailableHotkey("cmdShift", "Digit1", 1, "Toggle Header Visibility", toggleHeader);
    if (elements.native.tabsPanel)
      setAvailableHotkey("cmdShift", "Digit2", 2, "Toggle Tabs Panel Visibility", toggleTabsPanel);
  }
  function syncCmdCtrlHotkeys() {
    const editorExists = elements.native.editorPanel;
    const copyCodeBtnExists = document.querySelector(".btn-copy-code");
    const exerciseCompletionBtnExists = document.querySelector(
      ".instructions-panel .gray-links form button[type=submit]"
    );
    const submitReviewBtnExists = document.querySelector("#lsbot-send-review");
    const handleCopyCodeHotkey = () => {
      const triggerCopyBtn = () => {
        const copyBtn = document.querySelector(".btn-copy-code");
        copyBtn.dispatchEvent(
          new MouseEvent("mousedown", {
            bubbles: true,
            cancelable: true,
            button: 0
          })
        );
        copyBtn.click();
        if (elements.native.scratchpad) showToast("Scratchpad code copied");
        else if (elements.native.editorPanel) showToast("Editor code copied");
        else showToast("Code copied");
      };
      let label;
      if (elements.native.scratchpad) label = "Copy Scratchpad Code";
      else label = "Copy Editor Code";
      setAvailableHotkey("cmdCtrl", "KeyC", "C", label, triggerCopyBtn);
    };
    const handleEditorHotkey = (modifier) => {
      const editorPanel = elements.native.editorPanel;
      let focusEl;
      let label;
      const focusEditorPanel = () => {
        const codeEditor = editorPanel.querySelector(".CodeMirror textarea");
        if (codeEditor) handleFocus(codeEditor);
      };
      const focusScratchpad = () => {
        const scratchpadTab = document.querySelector(".tab-button[data-tab='code-editor']");
        if (scratchpadTab) activateTab(scratchpadTab);
      };
      if (editorExists) {
        focusEl = focusEditorPanel;
        label = "Focus Editor";
      } else {
        focusEl = focusScratchpad;
        label = "Focus Scratchpad Editor";
      }
      setAvailableHotkey(modifier, "KeyE", "E", label, focusEl);
    };
    const handleNextExerciseHotkey = () => {
      showToast("Going to next exercise");
      elements.native.nextExerciseButton.click();
    };
    const handleSubmitReviewHotkey = () => {
      const reviewSubmitBtn = document.querySelector("#lsbot-send-review");
      const reviewTabBtn = document.querySelector(".tab-button[data-tab='submit-review']");
      activateTab(reviewTabBtn);
      setTimeout(() => {
        reviewSubmitBtn.click();
      }, 100);
      showToast("Solution submitted for LSBot Review");
    };
    const handleTabsHotkeys = () => {
      const allTabBtns = document.querySelectorAll(".tab-button");
      const tabs = [];
      allTabBtns.forEach((btn) => {
        const isHidden = getComputedStyle(btn).display === "none";
        if (isHidden) return;
        const label = btn.getAttribute("aria-label") || btn.textContent.trim();
        const fullLabel = `Focus ${label} Tab`;
        tabs.push([btn, fullLabel]);
      });
      tabs.forEach((tab, index) => {
        const btnEl = tab[0];
        const btnLabel = tab[1];
        const key = index + 1;
        const eventCode = `Digit${key}`;
        const triggerTab = () => activateTab(btnEl);
        setAvailableHotkey("cmdCtrl", eventCode, key, btnLabel, triggerTab);
      });
    };
    if (elements.native.tabNav) handleTabsHotkeys();
    if (copyCodeBtnExists) handleCopyCodeHotkey();
    if (editorExists || elements.native.scratchpad) handleEditorHotkey("cmdCtrl");
    if (exerciseCompletionBtnExists)
      setAvailableHotkey("cmdCtrl", "KeyM", "M", "Toggle Exercise Completion Status", toggleExerciseCompletionStatus);
    if (elements.native.nextExerciseButton)
      setAvailableHotkey("cmdCtrl", "KeyN", "N", "Go to next exercise", handleNextExerciseHotkey);
    if (submitReviewBtnExists) setAvailableHotkey("cmdCtrl", "KeyR", "R", "Submit Review", handleSubmitReviewHotkey);
    if (elements.native.tocButton)
      setAvailableHotkey("cmdCtrl", "KeyT", "T", "Toggle Table of Content Visibility", toggleTocMenu);
    if (elements.injected.settingsMenu)
      setAvailableHotkey("cmdCtrl", "Comma", ",", "Toggle Settings Visibility", toggleSettings);
  }

  // src/js/modules/utils/sync/injected-elements-state.js
  function syncInjectedElementsState() {
    const header = document.querySelector(".site-header");
    const settingsMenu = document.querySelector(".settings-container");
    const settingsToggleBtn = document.querySelector(".btn--toggle-settings");
    const sidebarHiddenHeadersToggler = document.querySelector("#setting--sidebar-hidden-headers");
    const sidebarShrinkToggler = document.querySelector("#setting--sidebar-shrink");
    const sidebarToggleBtn = document.querySelector(".btn--toggle-sidebar");
    const tabsPanelToggleBtn = document.querySelector(".btn--toggle-tabs-panel");
    setElementHeader(header);
    setElementSettingsMenu(settingsMenu);
    setElementSettingsToggleBtn(settingsToggleBtn);
    setElementSidebarHiddenHeadersToggler(sidebarHiddenHeadersToggler);
    setElementSidebarShrinkToggler(sidebarShrinkToggler);
    setElementSidebarToggleButton(sidebarToggleBtn);
    setElementTabsPanelToggleButton(tabsPanelToggleBtn);
    const isSettingSidebarShrinkOn = ui.sidebar.isSettingSidebarShrinkOn;
    if (isSettingSidebarShrinkOn) sidebarShrinkToggler.checked = true;
    const isSettingSidebarHiddenHeadersOn = ui.sidebar.isSettingSidebarHiddenHeadersOn;
    if (isSettingSidebarHiddenHeadersOn) sidebarHiddenHeadersToggler.checked = true;
  }

  // src/js/modules/utils/sync/loaded-elements-state.js
  function syncLoadedElementsState() {
    const header = elements.injected.header;
    const sidebar = elements.native.sidebar;
    const tabsPanel = elements.native.tabsPanel;
    const isHeaderHidden = ui.header.isHidden;
    const isSettingSidebarHiddenHeadersOn = ui.sidebar.isSettingSidebarHiddenHeadersOn;
    const isSettingSidebarShrinkOn = ui.sidebar.isSettingSidebarShrinkOn;
    const isTabsPanelHidden = ui.tabsPanel.isHidden;
    if (header && isHeaderHidden) hideHeader();
    if (tabsPanel && isTabsPanelHidden) {
      hideTabsPanel();
    } else if (tabsPanel) {
      showTabsPanel();
    }
    if (sidebar && isSettingSidebarHiddenHeadersOn) {
      elements.native.sidebar.classList.add("hide-section-headers");
    }
    if (sidebar && isSettingSidebarShrinkOn) {
      elements.native.sidebar.classList.add("shrink");
    }
  }

  // src/js/modules/utils/sync/native-elements-state.js
  function syncNativeElementsState() {
    const contentPanel = document.querySelector(".assignment-content-panel") || document.querySelector(".book-content-panel");
    const editorPanel = document.querySelector(".editor-panel");
    const scratchpad = document.querySelector("#tab-code-editor");
    const instructionsPanel = document.querySelector(".instructions-panel");
    const sidebar = document.querySelector(".nav-drawer");
    const tabNav = document.querySelector(".tab-nav");
    const tabsPanel = document.querySelector(".tabs-panel");
    const tocButton = document.querySelector(".toc-toggle-button");
    setElementContentPanel(contentPanel);
    setElementEditorPanel(editorPanel);
    setElementInstructionsPanel(instructionsPanel);
    setElementScratchpad(scratchpad);
    setElementSidebar(sidebar);
    setElementTabNav(tabNav);
    setElementTabsPanel(tabsPanel);
    setElementTocButton(tocButton);
  }

  // src/js/modules/components/sidebar.js
  function updateSidebar() {
    const sidebarItemLinks = document.querySelectorAll(".nav-drawer > ul > li > a");
    const sidebar = document.querySelector(".sidebar.nav-drawer");
    if (sidebar) {
      syncActiveSidebarItem();
      return;
    }
    addSidebarLinkClasses();
    removeCountParentheses();
    sidebarItemLinks.forEach((link) => {
      if (!link) return;
      const linkParentElement = link.parentElement;
      const linkClassStr = link.getAttribute("class");
      let linkIconEl;
      let linkLabel;
      let dropdownItemIconEl;
      let tooltipFallback;
      const createSidebarLinkTooltip = (linkEl, tooltipText) => {
        const tooltipDataStr = tooltipText.replace(/\s+/g, "-").toLowerCase();
        const tooltipEl = document.createElement("div");
        const tooltipSpanEl = document.createElement("span");
        tooltipEl.classList.add("tooltip", "sidebar-tooltip", `sidebar-tooltip-${tooltipDataStr}`);
        tooltipSpanEl.textContent = tooltipText;
        tooltipEl.append(tooltipSpanEl);
        document.body.appendChild(tooltipEl);
        linkEl.setAttribute("aria-label", tooltipText);
        linkEl.setAttribute("data-tooltip", tooltipDataStr);
        linkEl.removeAttribute("title");
      };
      if (linkClassStr) {
        switch (true) {
          case linkClassStr.includes("courses"):
            linkLabel = "courses";
            linkIconEl = icons.sidebarIcons.courses();
            tooltipFallback = "Courses";
            break;
          case linkClassStr.includes("forum"):
            linkLabel = "forum";
            linkIconEl = icons.sidebarIcons.forum();
            tooltipFallback = "Forum";
            break;
          case linkClassStr.includes("events"):
            linkLabel = "events";
            linkIconEl = icons.sidebarIcons.events();
            tooltipFallback = "Events";
            break;
          case linkClassStr.includes("social"):
            linkLabel = "social";
            linkIconEl = icons.sidebarIcons.sharing();
            tooltipFallback = "Sharing";
            break;
          case linkClassStr.includes("videos"):
            linkLabel = "videos";
            linkIconEl = icons.sidebarIcons.videos();
            tooltipFallback = "Videos";
            break;
          case linkClassStr.includes("resources"):
            linkLabel = "resources";
            linkIconEl = icons.sidebarIcons.resources();
            tooltipFallback = "Resources";
            break;
          case linkClassStr.includes("my-exercises"):
            linkLabel = "my-exercises";
            linkIconEl = icons.sidebarIcons.myExercises();
            tooltipFallback = "My Exercises";
            break;
          case linkClassStr.includes("exercises"):
            linkLabel = "exercises";
            linkIconEl = icons.sidebarIcons.exercises();
            tooltipFallback = "Exercises";
            break;
          case linkClassStr.includes("bookshelf"):
            linkLabel = "bookshelf";
            linkIconEl = icons.sidebarIcons.bookshelf();
            tooltipFallback = "Bookshelf";
            break;
          case linkClassStr.includes("pages"):
            linkLabel = "pages";
            linkIconEl = icons.sidebarIcons.pages();
            dropdownItemIconEl = () => icons.sidebarIcons.page();
            tooltipFallback = "Pages";
            break;
          case linkClassStr.includes("archives"):
            linkLabel = "archives";
            linkIconEl = icons.sidebarIcons.archives();
            tooltipFallback = "Archives";
            break;
          case linkClassStr.includes("chat"):
            linkLabel = "chat";
            linkIconEl = icons.sidebarIcons.chat();
            tooltipFallback = "Chat Room";
            break;
          case linkClassStr.includes("my-account"):
            linkLabel = "my-account";
            linkIconEl = icons.sidebarIcons.myAccount();
            tooltipFallback = "My Account";
            break;
          case linkClassStr.includes("my-assessments"):
            linkLabel = "my-assessments";
            linkIconEl = icons.sidebarIcons.myAssessments();
            tooltipFallback = "My Assessments";
            break;
          case linkClassStr.includes("exit"):
            linkLabel = "sign-out";
            linkIconEl = icons.sidebarIcons.signOut();
            tooltipFallback = "Sign Out";
            break;
          default:
            linkLabel = null;
            linkIconEl = null;
            tooltipFallback = null;
            break;
        }
        const tooltipText = link.innerText.replace(/\([^)]*\)/g, "").trim() || tooltipFallback;
        createSidebarLinkTooltip(link, tooltipText);
        if (linkLabel && linkParentElement) setSidebarListsElement(linkParentElement, linkLabel);
        if (linkIconEl) link.prepend(linkIconEl);
        if (dropdownItemIconEl) {
          const sidebarDropdownLinks = document.querySelectorAll(".nav-drawer li.has-dropdown ul.dropdown li a");
          if (sidebarDropdownLinks.length > 0) {
            sidebarDropdownLinks.forEach((dropdownLink) => {
              dropdownLink.prepend(dropdownItemIconEl());
            });
          }
        }
        if (linkLabel === "pages") {
          const btnEl = document.createElement("button");
          btnEl.innerHTML = link.innerHTML;
          btnEl.className = link.className;
          for (const attr of link.attributes) {
            if (attr.name.startsWith("data-")) {
              btnEl.setAttribute(attr.name, attr.value);
            }
          }
          if (link.hasAttribute("aria-label")) {
            btnEl.setAttribute("aria-label", link.getAttribute("aria-label"));
          }
          link.replaceWith(btnEl);
        }
      }
    });
    reorderSidebarLists();
    injectSidebarHeader();
    syncActiveSidebarItem();
  }
  function addSidebarLinkClasses() {
    const sidebar = document.querySelector(".nav-drawer");
    const assessmentLink = sidebar.querySelector(".assessments");
    const exercisesLinks = sidebar.querySelectorAll(".exercises");
    if (!assessmentLink || exercisesLinks.length < 1) return;
    assessmentLink ? assessmentLink.classList.add("my-assessments") : null;
    exercisesLinks.forEach((link) => {
      const linkTitleStr = link.getAttribute("title");
      if (linkTitleStr?.includes("My Exercises")) {
        link.classList.add("my-exercises");
      }
    });
  }
  function injectSidebarHeader() {
    const sidebar = document.querySelector(".nav-drawer");
    const createSidebarHeader = () => {
      const sidebarHeaderEl = document.createElement("header");
      sidebarHeaderEl.className = "sidebar-header";
      const sidebarHeaderLogoEl = document.createElement("a");
      sidebarHeaderLogoEl.setAttribute("href", "/course_catalog");
      sidebarHeaderLogoEl.className = "sidebar-header__logo";
      const sidebarLogoTextEl = document.createElement("span");
      sidebarLogoTextEl.className = "logo-title hidden-on-collapse";
      sidebarLogoTextEl.textContent = "LaunchSchool";
      const modifiedLogoIconEl = icons.sidebarIcons.modifiedLogo();
      modifiedLogoIconEl.classList.add("logo-icon");
      sidebarHeaderLogoEl.appendChild(modifiedLogoIconEl);
      sidebarHeaderLogoEl.appendChild(sidebarLogoTextEl);
      sidebarHeaderEl.appendChild(sidebarHeaderLogoEl);
      return sidebarHeaderEl;
    };
    if (sidebar) sidebar.prepend(createSidebarHeader());
  }
  function removeCountParentheses() {
    const counts = document.querySelectorAll('.nav-drawer [class*="_unread_count"]');
    if (counts.length < 1) return;
    counts.forEach((count) => {
      const runWhenHasCountText = () => {
        const countText = count.textContent.trim();
        if (!countText) return;
        observer.disconnect();
        const newCountEl = document.createElement("span");
        newCountEl.className = "unread-count";
        newCountEl.textContent = countText.replace(/[()]/g, "");
        if (newCountEl.textContent === "1") newCountEl.classList.add("hide-single-count");
        count.after(newCountEl);
      };
      const observer = new MutationObserver(runWhenHasCountText);
      observer.observe(count, {
        childList: true,
        characterData: true,
        subtree: true
      });
      setTimeout(() => {
        observer.disconnect();
      }, 1500);
      runWhenHasCountText();
    });
  }
  function reorderSidebarLists() {
    const sidebar = document.querySelector(".nav-drawer");
    sidebar.classList.add("sidebar");
    const updatedListsWrapperEl = document.createElement("div");
    updatedListsWrapperEl.className = "sidebar-lists";
    const sidebarListsNames = Object.keys(sidebarLists);
    sidebarListsNames.forEach((listName) => {
      const listClassName = listName.replace(/([A-Z])/g, "-$1").toLowerCase();
      const listWrapperEl = document.createElement("div");
      listWrapperEl.className = `sidebar-list-wrapper ${listClassName}-wrapper`;
      const listEl = document.createElement("ul");
      listEl.className = `sidebar-list ${listClassName}`;
      for (const [listKey, listProperties] of Object.entries(sidebarLists)) {
        if (listKey === listName) {
          for (const [propertyKey, propertyValue] of Object.entries(listProperties)) {
            if (propertyKey === "listElements") {
              propertyValue.forEach((item) => {
                const itemLinks = item.querySelectorAll("a");
                itemLinks.forEach((link) => link?.classList.add("item-link"));
                const itemBtns = item.querySelectorAll("button");
                itemBtns.forEach((btn) => btn?.classList.add("item-btn"));
                item.className = "sidebar-list__item";
                listEl.appendChild(item);
              });
            }
            if (propertyKey === "listTitle") {
              const listHeaderEl = document.createElement("button");
              listHeaderEl.className = "sidebar-list-toggle-btn btn--plain";
              const listHeaderTitleEl = document.createElement("span");
              listHeaderTitleEl.className = "list-title";
              listHeaderTitleEl.innerText = propertyValue;
              listHeaderEl.appendChild(listHeaderTitleEl);
              listHeaderEl.appendChild(icons.sidebarIcons.toggle());
              listWrapperEl.appendChild(listHeaderEl);
            }
          }
        }
      }
      listWrapperEl.appendChild(listEl);
      updatedListsWrapperEl.appendChild(listWrapperEl);
    });
    if (sidebar) sidebar.appendChild(updatedListsWrapperEl);
  }

  // src/js/modules/components/toaster.js
  function injectToaster() {
    const createToaster = () => {
      const toasterEl = document.createElement("div");
      toasterEl.classList.add("toast-container");
      return toasterEl;
    };
    document.body.appendChild(createToaster());
  }

  // src/js/modules/utils/helpers/hide.js
  function hideHeader() {
    setIsHeaderHidden(true);
  }
  function hideSettings() {
    const settingsMenu = elements.injected.settingsMenu;
    const settingsToggleBtn = elements.injected.settingsToggleButton;
    settingsMenu.classList.remove("active");
    settingsToggleBtn.classList.remove("active");
    document.removeEventListener("pointerdown", handleOutsideSettingsMenuClick);
    document.removeEventListener("keydown", handleSettingsEsc);
  }
  function hideSidebar() {
    setIsSidebarCollapsed(true);
  }
  function hideTabsPanel() {
    setIsTabsPanelHidden(true);
  }
  function hideTocMenu() {
    const tocBtn = elements.native.tocButton;
    if (tocBtn) tocBtn.click();
  }

  // src/js/modules/utils/helpers/load.js
  function loadUI() {
    injectStyles();
    syncNativeElementsState();
    injectHeader();
    injectToaster();
    syncInjectedElementsState();
    updateSidebar();
    injectContentSolutionButtons();
    updateConversationHistoryButton();
    updateConversationNewButton();
    updateCopyCodeButton();
    updateCopyMarkupButton();
    updateExerciseCompletionButton();
    updateNextExerciseButton();
    updatePaginationButton();
    updateRunCodeButton();
    updateSolutionButton();
    updateTabButtons();
    updateWorkInEditorButton();
    syncAvailableHotkeys();
    injectHotkeysSection();
    syncLoadedElementsState();
    watchForMissingHeader();
    watchForUrlChange();
    watchHotkeys();
    watchPromptSubmission();
    watchQuestionBoxes();
    watchSettingSidebarHiddenHeadersToggler();
    watchSettingSidebarShrinkToggler();
    watchSettingsToggleBtn();
    watchSidebarLinks();
    watchSidebarToggleBtn();
    watchTabBtns();
    watchTabsPanelToggleBtn();
    watchNextExerciseBtn();
  }
  function scheduleReload() {
    if (ui.load.isReloadScheduled) {
      return;
    }
    setIsReloadScheduled(true);
    const reloadUI = () => {
      loadUI();
      setLastUrl();
      setIsReloadScheduled(false);
    };
    const startWait = performance.now();
    const waitForDom = () => {
      const isNewBody = document.body !== ui.load.previousBody;
      const isWaitMaxReached = performance.now() - startWait > 3e3;
      if (isNewBody) {
        requestAnimationFrame(reloadUI);
        return;
      } else if (isWaitMaxReached) {
        requestAnimationFrame(reloadUI);
        return;
      } else {
        requestAnimationFrame(waitForDom);
      }
    };
    requestAnimationFrame(waitForDom);
  }

  // src/js/modules/utils/helpers/show.js
  function showHeader() {
    setIsHeaderHidden(false);
  }
  function showSettings() {
    const settingsMenu = elements.injected.settingsMenu;
    const settingsToggleBtn = elements.injected.settingsToggleButton;
    settingsMenu.classList.add("active");
    settingsToggleBtn.classList.add("active");
    const openedTocMenu = document.querySelector(".toc-toggle-button.open");
    if (openedTocMenu) openedTocMenu.click();
    document.addEventListener("pointerdown", handleOutsideSettingsMenuClick);
    document.addEventListener("keydown", handleSettingsEsc);
  }
  function showSidebar() {
    setIsSidebarCollapsed(false);
  }
  function showTabsPanel() {
    setIsTabsPanelHidden(false);
  }
  function showToast(message, styleClass = null, duration = 2500) {
    const toastContainer = document.querySelector(".toast-container");
    const createToastEl = () => {
      const toastEl = document.createElement("div");
      toastEl.className = "toast";
      toastEl.textContent = message;
      if (styleClass) toastEl.classList.add(styleClass);
      toastContainer.appendChild(toastEl);
      return toastEl;
    };
    const toast = createToastEl();
    requestAnimationFrame(() => {
      toast.classList.add("show");
    });
    setTimeout(() => {
      toast.classList.remove("show");
      toast.addEventListener("transitionend", () => toast.remove(), { once: true });
    }, duration);
  }
  function showTocMenu() {
    const tocBtn = elements.native.tocButton;
    if (tocBtn) {
      tocBtn.click();
      const settingsMenu = elements.injected.settingsMenu;
      if (settingsMenu && settingsMenu.classList.contains("active")) hideSettings();
    }
  }

